<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,LearningTask,ProgrammeOutcome,OperationalFollowup as Followup,ApprenticeExperienceEntry};
use App\Support\{OperationalFollowups as F,StaffAttention,ReviewedImports};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Mail,Http};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class OperationalFollowupsTest extends TestCase {
 use LazilyRefreshDatabase;
 private function f():array {$admin=User::factory()->create(['role'=>'admin']);$tutor=User::factory()->create(['role'=>'tutor']);$mentor=User::factory()->create(['role'=>'mentor']);$other=User::factory()->create(['role'=>'tutor']);$a=Apprentice::factory()->create(['tutor_id'=>$tutor->id,'mentor_id'=>$mentor->id,'start_date'=>today()->subMonths(2)]);ProgrammeOutcome::factory()->create(['apprentice_id'=>$a->id,'context'=>['status'=>'Active','sourceRef'=>'Fictional checked status']]);$task=LearningTask::factory()->create(['apprentice_id'=>$a->id,'due_date'=>today()->subDay()]);return compact('admin','tutor','mentor','other','a','task');}
 private function key(array $f,string $kind='task',?User $u=null):string {$items=F::reasons($u??$f['tutor']);$found=collect($items)->first(fn($x)=>$x['apprentice']->id===$f['a']->id&&$x['reason']['kind']===$kind);$this->assertNotNull($found);return $found['key'];}
 private function start(array $f,?string $token=null):Followup {return F::start($f['tutor'],1,$f['a'],$this->key($f),$f['tutor'],$token??(string)Str::uuid(),today()->addDays(3)->toDateString(),'Fictional safe follow-up reference');}
 private function reject(callable $fn):void {try{$fn();$this->fail('Expected checked rejection');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 public function test_source_linked_start_preserves_task_and_records_owner():void {$f=$this->f();$before=$f['task']->fresh()->getAttributes();$x=$this->start($f);$this->assertSame($f['tutor']->id,$x->owner_id);$this->assertSame('In progress',$x->status);$this->assertSame($before,$f['task']->fresh()->getAttributes());$this->assertTrue(F::intact($x));}
 public function test_resolving_followup_does_not_complete_underlying_task_or_clear_flag():void {$f=$this->f();$x=$this->start($f);$key=$x->source_key;F::update($f['tutor'],1,$x,1,'Resolved',$f['tutor'],today()->toDateString(),'Follow-up discussion completed');$this->assertSame('Draft',$f['task']->fresh()->status);$this->assertArrayHasKey($key,F::reasons($f['tutor']));$this->assertNull($x->fresh()->open_key);}
 public function test_waiting_is_durable_and_separate_from_source_work():void {$f=$this->f();$x=$this->start($f);F::update($f['tutor'],1,$x,1,'Waiting',$f['tutor'],today()->addDays(5)->toDateString(),'Waiting for checked employer response');$this->assertSame('Waiting',$x->fresh()->status);$this->assertSame('Draft',$f['task']->fresh()->status);}
 public function test_cleared_source_keeps_followup_for_explicit_staff_check():void {$f=$this->f();$x=$this->start($f);$f['task']->forceFill(['status'=>'Approved'])->save();$this->assertArrayNotHasKey($x->source_key,F::reasons($f['tutor']));$this->assertSame(1,F::visible($f['tutor'])->count());$this->actingAs($f['tutor'])->get('/staff-follow-up')->assertOk()->assertSee('Original alert cleared or changed');}
 public function test_source_key_cannot_be_forged_or_used_for_another_apprentice():void {$f=$this->f();$other=Apprentice::factory()->create(['tutor_id'=>$f['tutor']->id]);$this->actingAs($f['tutor'])->post('/staff-follow-up/apprentice/'.$other->id,['source_key'=>$this->key($f),'owner_id'=>$f['tutor']->id,'request_token'=>(string)Str::uuid(),'due'=>today()->toDateString(),'reference'=>'Checked reference','confirmed'=>1])->assertForbidden();$this->assertDatabaseCount('operational_followups',0);}
 public function test_unassigned_or_inactive_owner_is_rejected():void {$f=$this->f();$key=$this->key($f);$this->actingAs($f['tutor'])->post('/staff-follow-up/apprentice/'.$f['a']->id,['source_key'=>$key,'owner_id'=>$f['other']->id,'request_token'=>(string)Str::uuid(),'due'=>today()->toDateString(),'reference'=>'Checked reference','confirmed'=>1])->assertForbidden();$f['other']->forceFill(['active'=>false])->save();$this->assertFalse(F::allowed($f['other'],$f['a'],'task'));}
 public function test_mentor_cannot_claim_training_task_but_can_follow_review_source():void {$f=$this->f();$this->assertFalse(F::allowed($f['mentor'],$f['a'],'task'));$key=$this->key($f,'review',$f['mentor']);$x=F::start($f['mentor'],1,$f['a'],$key,$f['mentor'],(string)Str::uuid(),today()->addDay()->toDateString(),'Checked review follow-up');$this->assertSame('review',$x->source_kind);}
 public function test_private_help_body_and_count_do_not_enter_desk():void {$f=$this->f();ApprenticeExperienceEntry::create(['apprentice_id'=>$f['a']->id,'requester_id'=>$f['tutor']->id,'request_token'=>(string)Str::uuid(),'history'=>[],'kind'=>'help_private','state'=>'New','title'=>'PRIVATE-HELP-TITLE-43','detail'=>'PRIVATE-HELP-BODY-43']);$this->actingAs($f['tutor'])->get('/staff-follow-up')->assertOk()->assertDontSee('PRIVATE-HELP')->assertDontSee('Private support');$all=json_encode(array_map(fn($x)=>$x['reason'],F::reasons($f['tutor'])));$this->assertStringNotContainsString('PRIVATE-HELP',$all);}
 #[\PHPUnit\Framework\Attributes\TestWith(['apprentice'])] #[\PHPUnit\Framework\Attributes\TestWith(['employer'])] #[\PHPUnit\Framework\Attributes\TestWith(['manager'])]
 public function test_unrelated_roles_cannot_read_or_write_desk(string $role):void {$f=$this->f();$u=User::factory()->create(['role'=>$role]);$this->actingAs($u)->get('/staff-follow-up')->assertForbidden();$this->post('/staff-follow-up/apprentice/'.$f['a']->id,[])->assertForbidden();}
 public function test_unassigned_tutor_cannot_read_named_followup_or_reclaim_it():void {$f=$this->f();$x=$this->start($f);$this->assertCount(0,F::visible($f['other']));$this->actingAs($f['other'])->post('/staff-follow-up/'.$x->id,['version'=>1,'status'=>'Resolved','owner_id'=>$f['other']->id,'due'=>today()->toDateString(),'reference'=>'Not assigned owner','confirmed'=>1])->assertForbidden();}
 public function test_reassignment_revokes_old_tutor_access_despite_record_ownership():void {$f=$this->f();$x=$this->start($f);$f['a']->update(['tutor_id'=>$f['other']->id]);$this->assertCount(0,F::visible($f['tutor']));$this->actingAs($f['tutor'])->post('/staff-follow-up/'.$x->id,['version'=>1,'status'=>'Waiting','owner_id'=>$f['tutor']->id,'due'=>today()->toDateString(),'reference'=>'Old owner blocked','confirmed'=>1])->assertForbidden();}
 public function test_only_manager_can_reassign_followup_owner():void {$f=$this->f();$x=$this->start($f);F::update($f['admin'],1,$x,1,'Waiting',$f['admin'],today()->addDay()->toDateString(),'Manager continuity allocation');$this->assertSame($f['admin']->id,$x->fresh()->owner_id);$this->actingAs($f['tutor'])->post('/staff-follow-up/'.$x->id,['version'=>2,'status'=>'Waiting','owner_id'=>$f['tutor']->id,'due'=>today()->toDateString(),'reference'=>'No longer owner','confirmed'=>1])->assertForbidden();}
 public function test_stale_followup_version_cannot_overwrite_another_update():void {$f=$this->f();$x=$this->start($f);F::update($f['tutor'],1,$x,1,'Waiting',$f['tutor'],today()->toDateString(),'First update');$this->reject(fn()=>F::update($f['tutor'],1,$x,1,'Resolved',$f['tutor'],today()->toDateString(),'Stale update'));}
 public function test_exact_request_replay_is_idempotent():void {$f=$this->f();$token=(string)Str::uuid();$a=$this->start($f,$token);$b=$this->start($f,$token);$this->assertSame($a->id,$b->id);$this->assertDatabaseCount('operational_followups',1);}
 public function test_duplicate_open_source_and_conflicting_token_do_not_duplicate():void {$f=$this->f();$this->start($f);$this->reject(fn()=>$this->start($f));$this->assertDatabaseCount('operational_followups',1);}
 public function test_closed_followup_cannot_be_silently_reopened_but_new_work_is_possible():void {$f=$this->f();$x=$this->start($f);F::update($f['tutor'],1,$x,1,'Resolved',$f['tutor'],today()->toDateString(),'Checked and closed');$this->reject(fn()=>F::update($f['tutor'],1,$x->refresh(),2,'Waiting',$f['tutor'],today()->toDateString(),'Silent reopen'));$next=$this->start($f);$this->assertNotSame($x->id,$next->id);$this->assertDatabaseCount('operational_followups',2);}
 public function test_missing_reference_and_past_due_creation_are_rejected():void {$f=$this->f();$key=$this->key($f);$this->reject(fn()=>F::start($f['tutor'],1,$f['a'],$key,$f['tutor'],(string)Str::uuid(),today()->toDateString(),''));$this->reject(fn()=>F::start($f['tutor'],1,$f['a'],$key,$f['tutor'],(string)Str::uuid(),today()->subDay()->toDateString(),'Checked reference'));}
 public function test_encrypted_references_are_escaped_in_authorised_view():void {$f=$this->f();$key=$this->key($f);F::start($f['tutor'],1,$f['a'],$key,$f['tutor'],(string)Str::uuid(),today()->toDateString(),'<script>NO-RUN-43</script>');$this->assertStringNotContainsString('NO-RUN',DB::table('operational_followups')->value('details'));$this->actingAs($f['tutor'])->get('/staff-follow-up')->assertSee('&lt;script&gt;',false)->assertDontSee('<script>NO-RUN-43</script>',false);}
 public function test_tampered_state_is_held_and_update_refused():void {$f=$this->f();$x=$this->start($f);DB::table('operational_followups')->where('id',$x->id)->update(['status'=>'Resolved']);$this->assertFalse(F::intact($x->fresh()));$this->reject(fn()=>F::update($f['tutor'],1,$x,1,'Waiting',$f['tutor'],today()->toDateString(),'Cannot overwrite proof'));}
 public function test_required_audit_failure_rolls_back_followup_creation():void {$f=$this->f();AuditFault::install('followup_create_fault','portal_operations_events','Fictional failure','followup_started');try{$this->start($f);$this->fail('Expected fault');}catch(\Illuminate\Database\QueryException){$this->assertDatabaseCount('operational_followups',0);}}
 public function test_required_audit_failure_rolls_back_status_and_owner():void {$f=$this->f();$x=$this->start($f);AuditFault::install('followup_update_fault','portal_operations_events','Fictional failure','followup_updated');try{F::update($f['admin'],1,$x,1,'Resolved',$f['admin'],today()->toDateString(),'Checked outcome');$this->fail('Expected fault');}catch(\Illuminate\Database\QueryException){$this->assertSame('In progress',$x->fresh()->status);$this->assertSame($f['tutor']->id,$x->owner_id);}}
 public function test_search_and_state_filter_match_authorised_scope():void {$f=$this->f();$x=$this->start($f);$this->assertCount(1,F::visible($f['tutor'],$f['a']->reference,'In progress'));$this->assertCount(0,F::visible($f['tutor'],'no-such-reference','all'));$this->assertCount(0,F::visible($f['tutor'],null,'Resolved'));$this->actingAs($f['tutor'])->get('/staff-follow-up')->assertOk()->assertHeader('Referrer-Policy','no-referrer');}
 public function test_followups_send_no_messages_and_change_no_canonical_marks():void {Mail::fake();Http::preventStrayRequests();$f=$this->f();$this->start($f);$this->assertDatabaseCount('attendance_marks',0);$this->assertDatabaseCount('signed_review_records',0);$this->assertSame('Draft',$f['task']->fresh()->status);Mail::assertNothingSent();Http::assertNothingSent();}

 public function test_attention_starts_followup_and_desk_shows_only_saved_work():void
 {
     $f = $this->f();
     $attention = route('attention.index', ['reason' => 'task']);
     $start = route('operations-desk.start', $f['a']);
     $this->actingAs($f['tutor'])->get($attention)->assertOk()
         ->assertSee($start)->assertSee('Start a staff follow-up');
     $this->get(route('operations-desk.index'))->assertOk()
         ->assertSee('No recorded follow-ups')->assertDontSee($start);
     $this->from($attention)->post($start, [
         'source_key' => $this->key($f), 'request_token' => (string) Str::uuid(),
         'owner_id' => $f['tutor']->id, 'due' => today()->addDay()->toDateString(),
         'reference' => 'Fictional planned call', 'confirmed' => 1,
     ])->assertRedirect($attention)->assertSessionHasNoErrors();
     $record = Followup::sole();
     $this->get($attention)->assertOk()->assertSee('Open recorded follow-up')->assertDontSee($start);
     $this->get(route('operations-desk.index', ['followup' => $record->id]))->assertOk()->assertSee('Update follow-up');
     $this->actingAs($f['other'])->get(route('operations-desk.index', ['followup' => $record->id]))->assertNotFound();
 }
}
